# Medicine guides, November 2026 batch. Run: python3 _scripts/gen_sheets.py _scripts/sheets/meds_nov26.py
V, C, U, R, VR = ("v", "Very common", "more than 1 in 10"), ("c", "Common", "1 in 10 to 1 in 100"), ("u", "Uncommon", "1 in 100 to 1 in 1,000"), ("r", "Rare", "1 in 1,000 to 1 in 10,000"), ("vr", "Very rare", "fewer than 1 in 10,000")
def g(t, items): return (t[0], t[1], t[2], items)
PBS = "https://www.pbs.gov.au/pbs/search?term="
HD = ("Healthdirect: Medicines information", "https://www.healthdirect.gov.au/medicines")

# ---------------- Memantine ----------------
med("memantine", "Memantine (Ebixa): Uses, Off-Label Uses and Side Effects",
 "Memantine explained: what it does in Alzheimer’s disease, the off-label uses with evidence (OCD, ADHD, pain), side effects, dosing and what it costs.",
 "Memantine", "Memantine",
 [("m", "NMDA receptor blocker"), ("l", "Prescription only (S4)")],
 "A dementia medicine that dampens overactive glutamate signalling in the brain. Also used off label, with mixed evidence, for OCD, ADHD and some pain.",
 "Memantine is a tablet approved for moderate to severe Alzheimer’s disease, where it slightly slows the loss of thinking and daily skills. Doctors sometimes use it off label, most often as an add-on for OCD, where the evidence is best. It’s usually well tolerated: dizziness, headache, constipation and sleepiness are the most common side effects.",
 [("For", "Moderate to severe Alzheimer’s disease (approved). Off label: OCD add-on, sometimes ADHD, autism and pain"),
  ("Works", "Small benefits in Alzheimer’s. In OCD, add-on trials show a modest extra drop in symptoms"),
  ("Cost", "$25 a script on the PBS for Alzheimer’s with an authority ($7.70 concession); private for other uses, and price varies"),
  ("Kicks in", "Weeks; judge it after 2–3 months at full dose"),
  ("Dose", "Starts at 5 mg and goes up weekly to 20 mg once a day; lower in kidney disease"),
  ("Watch for", "Dizziness, headache, constipation, sleepiness, raised blood pressure")],
 "Gentle, slow and modest. Not a cognitive enhancer for healthy brains, whatever the internet says.",
 ["Ebixa, and generic memantine brands"],
 "Memantine partly blocks NMDA receptors, which respond to glutamate, the brain’s main “go” signal. Too much glutamate activity is thought to harm nerve cells and drive repetitive, “stuck” loops of thought. Memantine turns down the background noise without blocking normal signalling.",
 ["Moderate to severe Alzheimer’s disease (TGA-approved), alone or with a donepezil-type medicine",
  "Off label, OCD: added to an SSRI when symptoms persist. Several small randomised trials and meta-analyses show a moderate extra benefit",
  "Off label, ADHD: small trials, mostly as an add-on in adults. Evidence is weak",
  "Off label, autism: early small studies looked promising; a large company trial for social symptoms didn’t show benefit",
  "Off label, pain and migraine prevention: small studies, mixed results"],
 "Most people get few side effects. Dizziness, headache, constipation and sleepiness are the most common, and usually settle. It can raise blood pressure a little.",
 [g(C, ["Dizziness", "Headache", "Sleepiness", "Constipation", "<b>Raised blood pressure</b>", "Shortness of breath", "Abnormal liver tests", "Allergic reactions (drug hypersensitivity)"]),
  g(U, ["Confusion or hallucinations", "Vomiting", "Tiredness", "Unsteady walking", "Fungal infections", "<b>Blood clots</b>", "<b>Heart failure</b>"]),
  g(VR, ["<b>Seizures</b>", "<b>Pancreatitis</b>", "<b>Psychotic reactions</b>"])],
 ["New confusion, hallucinations or agitation", "A seizure", "Severe stomach pain with vomiting", "Chest pain, breathlessness or leg swelling. Call 000 if severe"],
 ["Lower dose in moderate to severe kidney disease.", "Avoid combining with amantadine, ketamine or dextromethorphan (similar action).",
  "Things that make urine more alkaline (e.g. a strict vegetarian diet, large doses of antacids) can raise memantine levels.",
  "No withdrawal problems for most people, but stop through your doctor."],
 [("What is memantine used for?", "It’s approved for moderate to severe Alzheimer’s disease. Off label it’s sometimes added to an SSRI for OCD, and occasionally tried for ADHD, autism or pain, where the evidence is weaker."),
  ("Does memantine help OCD?", "As an add-on to an SSRI, small randomised trials and meta-analyses show a moderate extra improvement. It’s an off-label option, usually guided by a psychiatrist."),
  ("What are the side effects of memantine?", "Dizziness, headache, constipation and sleepiness are the most common. It can raise blood pressure slightly. Most people tolerate it well.")],
 [("Ebixa product information (TGA)", "https://www.ebs.tga.gov.au/"), ("PBS: Memantine", PBS + "memantine"),
  ("Modarresi A et al. Memantine augmentation in OCD: meta-analysis (2019, BMC Psychiatry)", "https://pubmed.ncbi.nlm.nih.gov/?term=memantine+obsessive+compulsive+meta-analysis"), HD],
 [("Lowering Your Dementia Risk", "/dementia-prevention/"), ("ADHD", "/adhd/"), ("Fluoxetine", "/medicines/fluoxetine/")],
 index_label="NMDA receptor blocker", blurb="A dementia medicine that dampens overactive glutamate signalling. Also used off label, mostly as an add-on for OCD.")

# ---------------- Lamotrigine ----------------
med("lamotrigine", "Lamotrigine (Lamictal): Rash Warning, Uses and Side Effects",
 "Lamotrigine explained: epilepsy and bipolar depression prevention, why the slow start matters for rash, the pill interaction, side effects and pregnancy.",
 "Lamotrigine", "Lamotrigine",
 [("m", "Anticonvulsant and mood stabiliser"), ("l", "Prescription only (S4)")],
 "A seizure medicine that also prevents bipolar depression. Usually easy to take, as long as it’s started slowly.",
 "Lamotrigine treats epilepsy and helps prevent depressive episodes in bipolar disorder. It must be started at a low dose and increased slowly over about 6 weeks, because going too fast raises the risk of a rare, serious rash. Any new rash in the first 2 months needs a same-day check. The combined pill lowers lamotrigine levels, and valproate doubles them.",
 [("For", "Epilepsy; preventing depression in bipolar disorder"),
  ("Works", "Good seizure control for many; better at preventing bipolar lows than highs"),
  ("Cost", "$25 a script on the PBS for epilepsy ($7.70 concession); other uses private, usually cheap as a generic"),
  ("Kicks in", "The dose build-up takes about 6 weeks; mood benefit builds over months"),
  ("Dose", "Slow build-up from 25 mg; halve the steps with valproate; higher doses with the combined pill or some seizure medicines"),
  ("Watch for", "Any rash in the first 8 weeks, dizziness, double vision, headache, nausea")],
 "The tortoise of mood stabilisers: start slow, never rush, never restart at full dose after a break.",
 ["Lamictal, Lamidus, and generic lamotrigine brands"],
 "Lamotrigine calms overexcited nerve cells by blocking sodium channels and reducing glutamate release. That steadies the electrical storms of epilepsy and, through less understood ways, smooths out depressive swings in bipolar disorder.",
 ["Epilepsy: focal and generalised seizures, including Lennox-Gastaut syndrome (TGA-approved)",
  "Bipolar disorder: preventing depressive episodes (TGA-approved)",
  "Off label: sometimes added for treatment-resistant depression, borderline personality emotional swings, or nerve pain; evidence is limited"],
 "Most people tolerate it well. Headache, dizziness, double vision, tiredness and nausea are the common ones. A harmless rash affects up to about 1 in 10, but because a rash can also be the first sign of a rare, dangerous reaction, any rash needs a check.",
 [g(V, ["Headache", "<b>Rash</b>"]),
  g(C, ["Dizziness, unsteadiness or tremor", "Double or blurred vision", "Sleepiness or trouble sleeping", "Nausea, vomiting or diarrhoea", "Tiredness", "Irritability or aggression", "Joint or back pain"]),
  g(R, ["<b>Stevens-Johnson syndrome</b> (adults about 1 in 1,000; higher in children)", "<b>Aseptic meningitis</b>", "<b>DRESS</b> (rash, fever, swollen glands, liver or blood changes)"]),
  g(VR, ["<b>Toxic epidermal necrolysis</b>", "<b>HLH</b> (a severe immune reaction with fever and rash)", "<b>Liver failure</b>", "<b>Blood count problems</b>"])],
 ["Any rash, especially with fever, mouth or eye sores, blistering or peeling: stop and seek help the same day", "Fever with swollen glands, sore throat or feeling very unwell", "Severe headache with neck stiffness and fever", "Thoughts of self-harm. Call 000 or Lifeline 13 11 14"],
 ["<b>Missed more than 5 days?</b> Don’t restart at your usual dose. Ask for a new build-up plan.",
  "<b>The combined pill</b> roughly halves lamotrigine levels; levels bounce back in the pill-free week. Your doctor may adjust the dose.",
  "<b>Valproate</b> roughly doubles levels, so the dose is halved. Carbamazepine, phenytoin and rifampicin lower levels.",
  "<b>Pregnancy:</b> one of the safer seizure medicines. Levels fall in pregnancy, so plan with your doctor; take folic acid.",
  "Don’t stop suddenly if you have epilepsy."],
 [("Why does lamotrigine have to be started slowly?", "Going up slowly over about 6 weeks lowers the risk of a rare but serious rash such as Stevens-Johnson syndrome. Starting too high, or adding it to valproate without halving the dose, raises the risk."),
  ("What does a lamotrigine rash look like?", "Most rashes are mild, but any rash in the first 2 months needs a same-day check. Warning signs are fever, blistering, peeling, mouth or eye sores, or feeling unwell."),
  ("Does the pill affect lamotrigine?", "Yes. The combined pill roughly halves lamotrigine levels, which can mean breakthrough seizures or low mood. Levels rise again in the pill-free week. Your doctor may adjust the dose.")],
 [("Lamictal product information (TGA)", "https://www.ebs.tga.gov.au/"), ("PBS: Lamotrigine", PBS + "lamotrigine"), HD],
 [("Depression", "/depression/"), ("Sertraline", "/medicines/sertraline/"), ("Quetiapine", "/medicines/quetiapine/")],
 index_label="Anticonvulsant and mood stabiliser", blurb="A seizure medicine that also prevents bipolar depression. Easy to take, as long as it’s started slowly.")

# ---------------- Atomoxetine ----------------
med("atomoxetine", "Atomoxetine (Strattera): Non-Stimulant ADHD Medicine",
 "Atomoxetine for ADHD explained: how this non-stimulant works, why it takes weeks, side effects, the PBS and how it compares with stimulants.",
 "Atomoxetine", "Atomoxetine",
 [("m", "Non-stimulant ADHD medicine"), ("l", "Prescription only (S4)")],
 "A non-stimulant ADHD capsule that works all day, every day. Slower and a bit less powerful than stimulants, but no peaks, crashes or controlled-drug paperwork.",
 "Atomoxetine is a once- or twice-daily non-stimulant for ADHD. It takes 4–6 weeks to work, sometimes 12, and smooths symptoms across the whole day, including mornings and evenings. It’s a good option when stimulants don’t suit, cause anxiety or tics, or when misuse is a worry. Common side effects are nausea, less appetite, tiredness and, in adults, erection or ejaculation problems.",
 [("For", "ADHD in children 6+, teens and adults"),
  ("Works", "Helps about half to two-thirds of people; on average a bit less than stimulants"),
  ("Cost", "$25 a script on the PBS with an authority when stimulants are unsuitable ($7.70 concession); otherwise private"),
  ("Kicks in", "Some effect in 1–2 weeks; full effect at 4–6 weeks, up to 12"),
  ("Dose", "Based on weight in children; usually 40 mg rising to 80 mg daily in adults"),
  ("Watch for", "Nausea, less appetite, tummy pain, tiredness, higher pulse and blood pressure, low mood")],
 "No buzz, no crash, no S8 forms. The trade-off is patience: give it 6 weeks before you judge it.",
 ["Strattera, and generic atomoxetine brands"],
 "Atomoxetine blocks the reuptake of noradrenaline (and, in the front of the brain, dopamine), so more is available where attention and impulse control are managed. Unlike stimulants, it doesn’t act on the brain’s reward centre, so it isn’t habit-forming.",
 ["ADHD in children aged 6 and over, teenagers and adults (TGA-approved)",
  "Often chosen when stimulants cause anxiety, tics, poor sleep or appetite loss, or when misuse is a concern",
  "Can be combined with a stimulant under specialist guidance"],
 "Nausea, less appetite and tummy pain are the most common, especially early; taking it with food helps. Tiredness or trouble sleeping, mood changes and a slightly higher pulse and blood pressure are common. Adults may notice erection, ejaculation or period changes.",
 [g(V, ["Nausea, vomiting or tummy pain", "Less appetite", "Headache", "Sleepiness (children)", "Dry mouth (adults)", "Trouble sleeping (adults)"]),
  g(C, ["Tiredness, dizziness or irritability", "Low mood or anxiety", "Weight loss", "Constipation or indigestion", "Faster heartbeat or <b>raised blood pressure</b>", "Hot flushes, sweating or chills", "Erection or ejaculation problems, less libido, period pain", "Trouble passing urine", "Rash or itch"]),
  g(U, ["<b>Suicidal thoughts</b> (mainly children and teens)", "Fainting", "Muscle spasms", "Shortness of breath", "Palpitations"]),
  g(R, ["<b>Liver injury</b>", "<b>Seizures</b>", "Raynaud’s (cold, white fingers)", "Priapism (an erection lasting over 4 hours)"])],
 ["Thoughts of self-harm, or a big change in mood or behaviour. Call 000 or Lifeline 13 11 14", "Yellow skin or eyes, dark urine or itching with tummy pain (liver)", "An erection lasting more than 4 hours", "Chest pain, fainting or a racing heartbeat"],
 ["<b>Give it time.</b> Judge it at 6–12 weeks at the right dose.",
  "Not a controlled (S8) medicine: no state permit, and it’s fine to travel with.",
  "Some antidepressants (fluoxetine, paroxetine) and bupropion raise atomoxetine levels a lot. Tell your doctor what else you take.",
  "Not with MAO inhibitors. Caution with heart disease or high blood pressure: pulse and blood pressure are checked.",
  "Can be stopped without tapering, but symptoms return."],
 [("How long does atomoxetine take to work?", "Some effect may show in 1–2 weeks, but full benefit usually takes 4–6 weeks and can take up to 12. Judge it after that, at the right dose."),
  ("Is atomoxetine a stimulant?", "No. It’s a non-stimulant that works on noradrenaline. It isn’t habit-forming and isn’t a controlled (S8) medicine."),
  ("What are the side effects of atomoxetine?", "Nausea, tummy pain and less appetite are the most common, especially early. Tiredness, mood changes, higher pulse and blood pressure, and sexual side effects in adults can also happen. Low mood or suicidal thoughts in young people need urgent review.")],
 [("Strattera product information (TGA)", "https://www.ebs.tga.gov.au/"), ("PBS: Atomoxetine", PBS + "atomoxetine"), ("Australian evidence-based clinical practice guideline for ADHD (AADPA, 2022)", "https://adhdguideline.aadpa.com.au/"), HD],
 [("ADHD", "/adhd/"), ("Methylphenidate", "/medicines/methylphenidate/"), ("Guanfacine", "/medicines/guanfacine/")],
 index_label="Non-stimulant ADHD medicine", blurb="A non-stimulant ADHD capsule that works all day. Slower than stimulants, with no peaks, crashes or S8 paperwork.")

# ---------------- Bupropion ----------------
med("bupropion", "Bupropion (Zyban): Smoking, Off-Label Depression and ADHD Uses",
 "Bupropion explained: approved for quitting smoking in Australia, off-label use for depression, ADHD and SSRI sexual side effects, seizure risk and interactions.",
 "Bupropion", "Bupropion",
 [("m", "Smoking cessation aid; off-label antidepressant"), ("l", "Prescription only (S4)")],
 "A quit-smoking tablet that’s an antidepressant almost everywhere else. Energising rather than sedating, and kinder to libido and weight than most.",
 "In Australia, bupropion (Zyban) is approved and on the PBS for quitting smoking. Overseas it’s a common antidepressant, and doctors here sometimes use it off label for depression, low energy, ADHD and to counter sexual side effects from SSRIs. It doesn’t usually cause weight gain or sexual problems. The main risk is seizures, so it’s avoided in epilepsy, eating disorders and heavy alcohol withdrawal.",
 [("For", "Quitting smoking (approved). Off label: depression, ADHD, SSRI sexual side effects"),
  ("Works", "Roughly doubles the chance of quitting smoking compared with placebo"),
  ("Cost", "$25 a script on the PBS for smoking cessation ($7.70 concession); other uses private"),
  ("Kicks in", "For smoking, start 1–2 weeks before your quit date; for mood, 2–6 weeks"),
  ("Dose", "150 mg each morning for 3 days, then 150 mg twice a day, at least 8 hours apart; usually 7–12 weeks for smoking"),
  ("Watch for", "Trouble sleeping, dry mouth, headache, nausea, anxiety, raised blood pressure")],
 "The antidepressant that doesn’t flatten your libido or add kilos. The catch: seizure risk, so it’s not for everyone.",
 ["Zyban (sustained-release). Overseas brands include Wellbutrin"],
 "Bupropion blocks the reuptake of dopamine and noradrenaline, which lifts energy and motivation. It also blocks nicotine receptors, which takes the edge off cravings and withdrawal.",
 ["Quitting smoking, with support (TGA-approved)",
  "Off label, depression: approved overseas; useful when tiredness, low motivation, weight gain or sexual side effects are a problem",
  "Off label, SSRI sexual side effects: sometimes added to help",
  "Off label, ADHD: modest benefit in trials, less than stimulants",
  "Off label, weight: with naltrexone as Contrave (not PBS listed)"],
 "Trouble sleeping is the most common side effect; take the second dose by mid-afternoon. Dry mouth, headache, nausea and feeling anxious or shaky are also common. Seizures are uncommon to rare, more likely at higher doses or with risk factors.",
 [g(V, ["Trouble sleeping"]),
  g(C, ["Dry mouth", "Headache", "Nausea, tummy pain or constipation", "Anxiety, agitation or shakiness", "Dizziness", "Rash or itch", "Sweating", "Taste changes", "Fever", "Less appetite"]),
  g(U, ["<b>Raised blood pressure</b>", "Fast heartbeat", "Low mood or confusion", "Tinnitus", "Blurred vision"]),
  g(R, ["<b>Seizures</b> (about 1 in 1,000 at the usual dose)", "<b>Severe allergic reactions</b>", "Hallucinations or <b>psychosis</b>", "<b>Suicidal thoughts</b>"])],
 ["A seizure. Call 000", "Swelling of the face or throat, a widespread rash or trouble breathing", "Thoughts of self-harm. Call 000 or Lifeline 13 11 14", "Confusion, hallucinations or severe agitation"],
 ["<b>Not for people with</b> epilepsy or seizures, eating disorders (anorexia or bulimia), or who are suddenly stopping alcohol or sedatives.",
  "<b>Interactions:</b> it strongly blocks the liver enzyme CYP2D6, raising levels of some antidepressants, antipsychotics, beta blockers (e.g. metoprolol) and atomoxetine. It can make tamoxifen and codeine less effective.",
  "Keep alcohol low; it raises seizure risk.",
  "Don’t take two doses close together, and don’t crush or chew the tablets."],
 [("Is bupropion approved for depression in Australia?", "No. In Australia it’s approved (as Zyban) for quitting smoking. It’s an approved antidepressant in many other countries, and doctors here sometimes prescribe it off label for depression."),
  ("Does bupropion cause weight gain or sexual side effects?", "Usually not. It’s one of the few antidepressant-type medicines that tends not to cause weight gain or sexual problems, and it’s sometimes added to help SSRI sexual side effects."),
  ("Who shouldn’t take bupropion?", "People with epilepsy or past seizures, eating disorders, or who are suddenly stopping alcohol or sedatives, because it raises seizure risk. It also interacts with several medicines through CYP2D6.")],
 [("Zyban product information (TGA)", "https://www.ebs.tga.gov.au/"), ("PBS: Bupropion", PBS + "bupropion"), ("Cochrane: Antidepressants for smoking cessation (2020)", "https://www.cochranelibrary.com/cdsr/doi/10.1002/14651858.CD000031.pub5/full"), HD],
 [("Depression", "/depression/"), ("ADHD", "/adhd/"), ("Atomoxetine", "/medicines/atomoxetine/")],
 index_label="Smoking cessation aid", blurb="Approved here for quitting smoking; an antidepressant overseas. Off label for low mood, ADHD and SSRI sexual side effects.")

# ---------------- Goserelin ----------------
med("goserelin", "Zoladex (Goserelin) Implant: Uses and Side Effects",
 "Zoladex (goserelin) explained: how the implant switches off sex hormones for prostate cancer, breast cancer, endometriosis and fibroids, side effects and bone protection.",
 "Zoladex (Goserelin)", "Goserelin",
 [("m", "GnRH agonist (hormone blocker)"), ("l", "Prescription only (S4)")],
 "A tiny implant injected under the skin of the tummy that switches off the ovaries or testes for 1 or 3 months at a time. Powerful, reversible, and comes with a menopause-like package.",
 "Zoladex (goserelin) is an implant given into the skin of the tummy every 4 weeks (3.6 mg) or 12 weeks (10.8 mg). After an initial short surge, it shuts down oestrogen or testosterone. It treats prostate and breast cancer, endometriosis, and shrinks fibroids before surgery. Side effects come from low hormones: hot flushes, sweats, low libido, mood changes, vaginal dryness and bone thinning with longer use.",
 [("For", "Prostate cancer, breast cancer, endometriosis, fibroids before surgery, IVF"),
  ("Works", "Reliably switches off sex hormones within 3–4 weeks"),
  ("Cost", "$25 a script on the PBS for approved uses ($7.70 concession)"),
  ("Kicks in", "Hormones surge for about a week, then drop by 3–4 weeks"),
  ("Dose", "3.6 mg every 28 days or 10.8 mg every 12 weeks; endometriosis courses are usually up to 6 months"),
  ("Watch for", "Hot flushes, sweats, low libido, mood changes, headache, vaginal dryness, bone thinning")],
 "A medical menopause (or andropause) on demand. Effective, but plan the bone and mood protection before the first dose.",
 ["Zoladex 3.6 mg (monthly) and Zoladex LA 10.8 mg (3-monthly) implants"],
 "Goserelin is a copy of GnRH, the brain hormone that tells the pituitary to switch on the ovaries or testes. Given continuously instead of in pulses, it first overstimulates, then switches the system off, so oestrogen or testosterone drops to menopausal or castrate levels.",
 ["Prostate cancer: advanced or high-risk, often with radiotherapy (TGA-approved)",
  "Breast cancer: hormone-sensitive, in women before menopause (TGA-approved)",
  "Endometriosis: pain relief, usually for up to 6 months, often with add-back hormone therapy (TGA-approved)",
  "Fibroids: shrinking them and correcting anaemia before surgery (TGA-approved)",
  "IVF: suppressing natural cycles before stimulation"],
 "Nearly everyone gets low-hormone effects: hot flushes and sweats are very common, plus lower libido, mood changes and headaches. Women get vaginal dryness and periods stop; men may get erection problems and breast swelling. Longer courses thin the bones. In prostate cancer, symptoms can briefly flare in the first weeks.",
 [g(V, ["Hot flushes and sweating", "Lower libido", "Erection problems (men)", "Vaginal dryness, breast size change (women)", "Acne or skin reactions"]),
  g(C, ["Low mood or mood swings", "Headache", "Pins and needles", "<b>Bone thinning</b> and joint pain", "Weight gain", "Injection-site pain or bruising", "Breast swelling or tenderness (men)", "<b>Raised blood pressure</b>", "<b>Raised blood sugar</b>, <b>heart risk</b> (men on long-term treatment)", "Tumour flare in prostate cancer (bone pain, urine trouble) in the first weeks"]),
  g(U, ["Allergic reactions", "Raised calcium (breast cancer with bone spread)"]),
  g(R, ["<b>Pituitary bleeding</b> (sudden headache, vision loss)", "<b>Ovarian cysts</b>", "Low blood pressure, <b>injection-site bleeding</b>", "<b>Spinal cord compression</b> from flare in prostate cancer with spine spread"])],
 ["Sudden severe headache with vomiting or vision loss", "New back pain with leg weakness, numbness or bladder problems (prostate cancer). Call 000", "Heavy bleeding or a growing lump at the injection site", "Low mood with thoughts of self-harm. Call Lifeline 13 11 14"],
 ["<b>Bones:</b> for courses longer than a few months, ask about calcium, vitamin D, exercise and a bone density scan.",
  "<b>Add-back HRT</b> (a little oestrogen and progestogen) for endometriosis reduces flushes and bone loss without undoing the benefit.",
  "<b>Contraception:</b> periods usually stop, but use a non-hormonal method; it’s not a contraceptive and harms pregnancy.",
  "<b>Prostate cancer:</b> an anti-androgen tablet is often given for the first weeks to block the flare. Men on long-term treatment need heart, sugar and bone checks.",
  "Effects wear off over a few months after the last implant."],
 [("What is Zoladex used for?", "Prostate cancer, hormone-sensitive breast cancer before menopause, endometriosis, shrinking fibroids before surgery, and IVF. It switches off the body’s sex hormones."),
  ("What are the side effects of Zoladex?", "Mostly menopause-like effects from low hormones: hot flushes, sweats, low libido, mood changes, headaches, vaginal dryness and, over longer courses, bone thinning. Men may have erection problems and breast swelling."),
  ("Is Zoladex a contraceptive?", "No. Periods usually stop, but you should still use a non-hormonal contraceptive, because pregnancy is possible early on and the medicine can harm a pregnancy.")],
 [("Zoladex product information (TGA)", "https://www.ebs.tga.gov.au/"), ("PBS: Goserelin", PBS + "goserelin"), HD],
 [("Endometriosis", "/endometriosis/"), ("Visanne (Dienogest)", "/medicines/dienogest/"), ("Prostate Cancer", "/prostate-cancer/")],
 index_label="GnRH agonist implant", blurb="An implant that switches off sex hormones for 1 or 3 months. For prostate and breast cancer, endometriosis and fibroids.")

# ---------------- Dienogest ----------------
med("dienogest", "Visanne (Dienogest) for Endometriosis: Benefits and Side Effects",
 "Visanne (dienogest) explained: how this daily progestogen eases endometriosis pain, bleeding and spotting, mood, bones, contraception and cost in Australia.",
 "Visanne (Dienogest)", "Dienogest",
 [("m", "Progestogen"), ("l", "Prescription only (S4)")],
 "A once-daily progestogen tablet made for endometriosis. As good as hormone shut-down implants for pain, with far fewer menopause-type side effects.",
 "Visanne is a 2 mg dienogest tablet taken every day without a break to treat endometriosis pain. In trials it worked as well as GnRH agonists (like Zoladex) for pain, with fewer hot flushes and less bone loss. Irregular bleeding or spotting is common in the first months. It isn’t on the PBS, so it’s a private script. Use condoms or another non-hormonal method for contraception.",
 [("For", "Endometriosis pain"),
  ("Works", "Reduces pelvic pain for most; similar to GnRH agonists in head-to-head trials"),
  ("Cost", "Not on the PBS: a private script, with price varying by pharmacy"),
  ("Kicks in", "Pain usually eases over 1–3 months"),
  ("Dose", "One 2 mg tablet daily, continuously, at the same time each day"),
  ("Watch for", "Spotting or irregular bleeding, headache, breast discomfort, low mood, acne, weight change")],
 "A calmer alternative to a chemical menopause. The spotting is annoying but usually settles; low mood is the side effect to watch.",
 ["Visanne, and generic dienogest brands"],
 "Dienogest is a progestogen that thins endometriosis tissue, reduces its inflammation and new blood vessels, and partly lowers oestrogen without dropping it to menopausal levels.",
 ["Endometriosis (TGA-approved), including after surgery to reduce recurrence",
  "Often a first or second choice when the combined pill or other progestogens haven’t helped enough"],
 "Irregular bleeding or spotting is the most common side effect, especially in the first 3 months, and usually improves. Headache, breast discomfort, low mood, acne, hair thinning and weight gain are also common. Bone density can fall slightly in teenagers.",
 [g(C, ["Spotting or irregular bleeding (very common early on)", "Headache or migraine", "Breast discomfort", "Low mood, mood swings or poor sleep", "Lower libido", "Acne or hair loss", "Weight gain", "Hot flushes", "Nausea or tummy pain", "Ovarian cysts (usually harmless)", "Tiredness"]),
  g(U, ["Anxiety", "Vaginal discharge or dryness", "Itch or rash", "<b>Anaemia</b> from heavy bleeding", "Back pain"]),
  g(R, ["<b>Blood clots</b> (no proven extra risk, but stop and seek help with symptoms)"])],
 ["One-sided calf swelling or pain, sudden breathlessness or chest pain. Call 000", "Very heavy bleeding", "Severe low mood or thoughts of self-harm. Call Lifeline 13 11 14", "Sudden severe headache or vision changes"],
 ["<b>Contraception:</b> it usually stops ovulation but isn’t approved as a contraceptive. Use condoms or a copper IUD.",
  "<b>Teenagers:</b> bone density may fall a little; your doctor will weigh this up.",
  "<b>Low mood:</b> tell your doctor early if mood drops, especially with a past history of depression.",
  "Some medicines (e.g. some epilepsy medicines, rifampicin, St John’s wort) make it less effective.",
  "Missed a tablet? Take it as soon as you remember, then carry on."],
 [("How long does Visanne take to work?", "Pain usually eases over 1–3 months. Spotting is common at first and tends to settle with time."),
  ("Is Visanne a contraceptive?", "No. It usually stops ovulation, but it isn’t approved as a contraceptive, so use condoms or a copper IUD."),
  ("Is Visanne on the PBS?", "No. In Australia it’s a private prescription, and the price varies by pharmacy and brand.")],
 [("Visanne product information (TGA)", "https://www.ebs.tga.gov.au/"), ("Strowitzki T et al. Dienogest vs leuprolide acetate in endometriosis (2010, Human Reproduction)", "https://pubmed.ncbi.nlm.nih.gov/20089522/"), ("Endometriosis Australia", "https://www.endometriosisaustralia.org/"), HD],
 [("Endometriosis", "/endometriosis/"), ("Zoladex (Goserelin)", "/medicines/goserelin/"), ("Period Pain", "/period-pain/")],
 index_label="Progestogen for endometriosis", blurb="A daily progestogen tablet for endometriosis pain. As good as hormone shut-down for pain, with fewer side effects.")

# ---------------- Pregabalin ----------------
med("pregabalin", "Pregabalin (Lyrica): Nerve Pain, Side Effects and Dependence",
 "Pregabalin explained: what it helps (nerve pain) and what it doesn’t (sciatica, most back pain), dizziness and sleepiness, weight gain, misuse risk and stopping safely.",
 "Pregabalin", "Pregabalin",
 [("m", "Gabapentinoid (nerve pain medicine)"), ("l", "Prescription only (S4)")],
 "A nerve-pain capsule that helps a minority of people a lot and many people not at all. Worth a careful trial; not worth staying on if it isn’t clearly helping.",
 "Pregabalin (Lyrica) treats nerve pain, such as diabetic nerve pain, shingles pain and spinal cord injury pain, and is an add-on for epilepsy. Only about 1 in 4 to 1 in 3 people get a meaningful benefit. It doesn’t help sciatica or most back pain. Dizziness and sleepiness are very common, and weight gain, swelling and blurred vision are common. It can be misused and causes withdrawal if stopped suddenly, and it’s dangerous with opioids.",
 [("For", "Nerve (neuropathic) pain; add-on for focal epilepsy"),
  ("Works", "A meaningful benefit for a minority (about 1 in 4 to 1 in 3) with nerve pain"),
  ("Cost", "$25 a script on the PBS for neuropathic pain after other treatments ($7.70 concession)"),
  ("Kicks in", "Within 1–2 weeks; judge it after 4 weeks at a steady dose"),
  ("Dose", "Starts low (often 25–75 mg at night) and goes up slowly; lower in kidney disease"),
  ("Watch for", "Dizziness, sleepiness, unsteadiness, weight gain, swelling, blurred vision, feeling “high”")],
 "The “try it, then judge it honestly” medicine. If you can’t tell it’s helping at 4 weeks, it probably isn’t.",
 ["Lyrica, and generic pregabalin brands"],
 "Pregabalin attaches to calcium channels on overactive nerve endings and reduces the release of pain and excitement signals. It doesn’t touch ordinary inflammation pain.",
 ["Neuropathic pain, e.g. diabetic nerve pain, after shingles, spinal cord injury (TGA-approved)",
  "Add-on treatment for focal seizures (TGA-approved)",
  "Off label: fibromyalgia (modest benefit for some), generalised anxiety (approved overseas)",
  "<b>Doesn’t help:</b> sciatica (no better than placebo in a large Australian trial) or most low back pain"],
 "Dizziness and sleepiness affect more than 1 in 10. Weight gain, increased appetite, swelling of the legs, blurred vision, poor concentration, dry mouth and constipation are common. Some people feel euphoric, which is part of why it can be misused.",
 [g(V, ["Dizziness", "Sleepiness", "Headache"]),
  g(C, ["Weight gain and more appetite", "Swelling of hands, legs or feet", "Blurred or double vision", "Unsteadiness, falls, tremor", "Poor memory or concentration", "Feeling high, confused or irritable", "Dry mouth, constipation, nausea or bloating", "Erection problems", "Feeling drunk"]),
  g(U, ["Low mood or agitation", "Fainting", "<b>Breathing problems</b> (especially with opioids)", "Muscle pain", "Low blood sugar"]),
  g(R, ["<b>Severe allergic reactions</b> or angioedema", "<b>Heart failure</b>", "<b>Suicidal thoughts</b>", "<b>Kidney problems</b>"])],
 ["Slow or shallow breathing or extreme sleepiness, especially with opioids, alcohol or sedatives. Call 000", "Swelling of the face, lips or throat", "Thoughts of self-harm. Call Lifeline 13 11 14", "New breathlessness or major leg swelling"],
 ["<b>Opioids, alcohol, sleeping tablets:</b> combining raises the risk of overdose and breathing problems.",
  "<b>Driving:</b> don’t drive until you know how it affects you.",
  "<b>Stopping:</b> taper over at least a week; stopping suddenly can cause anxiety, sweats, insomnia, nausea and, rarely, seizures.",
  "<b>Misuse and dependence</b> happen, especially with a history of substance use.",
  "Lower doses in kidney disease. Ask before pregnancy."],
 [("Does pregabalin help sciatica?", "No. A large Australian randomised trial found pregabalin was no better than placebo for sciatica, and it caused more side effects."),
  ("How long does pregabalin take to work?", "Some benefit can start within 1–2 weeks. If you can’t clearly tell it’s helping after about 4 weeks at a steady dose, talk to your doctor about tapering off."),
  ("Can I stop pregabalin suddenly?", "It’s best not to. Taper over at least a week to avoid withdrawal symptoms such as anxiety, insomnia, sweats and nausea.")],
 [("Lyrica product information (TGA)", "https://www.ebs.tga.gov.au/"), ("PBS: Pregabalin", PBS + "pregabalin"),
  ("Mathieson S et al. Trial of pregabalin for acute and chronic sciatica (PRECISE, NEJM 2017)", "https://www.nejm.org/doi/full/10.1056/NEJMoa1614292"),
  ("Cochrane: Pregabalin for neuropathic pain in adults (2019)", "https://www.cochranelibrary.com/cdsr/doi/10.1002/14651858.CD007076.pub3/full"), HD],
 [("Sciatica", "/sciatica/"), ("Amitriptyline", "/medicines/amitriptyline/"), ("Duloxetine", "/medicines/duloxetine/"), ("Shingles", "/shingles/")],
 index_label="Gabapentinoid (nerve pain)", blurb="A nerve-pain capsule that helps a minority a lot. Doesn’t help sciatica. Dizziness, sleepiness and misuse risk.")

# ---------------- Duloxetine ----------------
med("duloxetine", "Duloxetine (Cymbalta): Depression, Anxiety and Pain",
 "Duloxetine explained: an SNRI for depression, anxiety, nerve pain, fibromyalgia and osteoarthritis pain. Nausea, how to start and stop, and interactions.",
 "Duloxetine", "Duloxetine",
 [("m", "SNRI antidepressant"), ("l", "Prescription only (S4)")],
 "An antidepressant that also turns down pain. Useful when low mood, anxiety and chronic pain arrive as a package deal.",
 "Duloxetine (Cymbalta) is an SNRI antidepressant used for depression, generalised anxiety and diabetic nerve pain, and widely used for fibromyalgia, osteoarthritis and chronic musculoskeletal pain. Nausea is the most common side effect; starting low and taking it with food helps. It shouldn’t be stopped suddenly, because withdrawal symptoms are common.",
 [("For", "Depression, generalised anxiety, diabetic nerve pain; also fibromyalgia and chronic musculoskeletal pain"),
  ("Works", "Similar to other antidepressants for mood; a meaningful pain benefit for about 1 in 4 to 1 in 3 with nerve pain or fibromyalgia"),
  ("Cost", "$25 a script on the PBS for depression ($7.70 concession); check the PBS for other uses"),
  ("Kicks in", "Pain: 1–2 weeks; mood and anxiety: 2–6 weeks"),
  ("Dose", "Often 30 mg for a week, then 60 mg once a day"),
  ("Watch for", "Nausea, dry mouth, constipation, sleepiness or insomnia, sweating, sexual side effects, raised blood pressure")],
 "Two jobs for one capsule: mood and pain. Start low, and never just stop it.",
 ["Cymbalta, Andepra, Coperin, and generic duloxetine brands"],
 "Duloxetine boosts serotonin and noradrenaline. In the brain that helps mood and anxiety; in the spinal cord it strengthens the body’s own “volume down” pathways for pain.",
 ["Major depression (TGA-approved)", "Generalised anxiety disorder (TGA-approved)", "Diabetic peripheral neuropathic pain (TGA-approved)",
  "Off label in Australia (approved overseas): fibromyalgia, chronic low back pain and osteoarthritis pain"],
 "Nausea affects more than 1 in 5 early on and usually settles within 1–2 weeks. Dry mouth, headache, sleepiness or trouble sleeping, dizziness, constipation, sweating, less appetite and sexual side effects are common. It can raise blood pressure a little.",
 [g(V, ["Nausea", "Headache", "Dry mouth", "Sleepiness"]),
  g(C, ["Dizziness or tiredness", "Trouble sleeping or vivid dreams", "Constipation, diarrhoea or indigestion", "Less appetite or weight change", "Sweating or hot flushes", "Less libido, erection or orgasm problems", "Anxiety or shakiness", "Blurred vision", "Palpitations, <b>raised blood pressure</b>"]),
  g(U, ["<b>Liver inflammation</b>", "Bruising or <b>bleeding</b>", "Trouble passing urine", "Mood swings", "<b>Suicidal thoughts</b> (young people)"]),
  g(R, ["<b>Serotonin syndrome</b>", "<b>Low sodium</b>", "<b>Mania</b>", "<b>Seizures</b>", "<b>Severe skin reactions</b>", "Glaucoma attack"])],
 ["Agitation, fever, sweating, shaking and a racing heart (serotonin syndrome), especially after adding another medicine. Call 000", "Thoughts of self-harm. Call 000 or Lifeline 13 11 14", "Yellow skin or eyes, dark urine", "Confusion, severe headache or a seizure"],
 ["<b>Stopping:</b> taper slowly with your doctor. Stopping suddenly often causes dizziness, “brain zaps”, nausea, irritability and poor sleep.",
  "<b>Interactions:</b> avoid with other serotonin medicines (e.g. tramadol, triptans in high use, St John’s wort) unless your doctor agrees; ciprofloxacin and fluvoxamine raise levels.",
  "<b>Bleeding:</b> risk rises with aspirin, anti-inflammatories and blood thinners.",
  "Avoid in heavy alcohol use or liver disease. Blood pressure is checked."],
 [("What is duloxetine used for?", "Depression, generalised anxiety and diabetic nerve pain. It’s also widely used for fibromyalgia, osteoarthritis and chronic back pain, which are approved uses overseas."),
  ("How do I stop duloxetine?", "Slowly, with your doctor. Stopping suddenly often causes dizziness, “brain zaps”, nausea and irritability."),
  ("Does duloxetine cause nausea?", "Yes, it’s the most common side effect at first, affecting more than 1 in 5 people. Starting at 30 mg and taking it with food helps, and it usually settles within 1–2 weeks.")],
 [("Cymbalta product information (TGA)", "https://www.ebs.tga.gov.au/"), ("PBS: Duloxetine", PBS + "duloxetine"),
  ("Cochrane: Duloxetine for painful neuropathy, chronic pain or fibromyalgia (2014)", "https://www.cochranelibrary.com/cdsr/doi/10.1002/14651858.CD007115.pub3/full"), HD],
 [("Depression", "/depression/"), ("Pregabalin", "/medicines/pregabalin/"), ("Amitriptyline", "/medicines/amitriptyline/"), ("Fibromyalgia", "/fibromyalgia/")],
 index_label="SNRI antidepressant", blurb="An antidepressant that also turns down pain. For depression, anxiety, nerve pain, fibromyalgia and arthritis pain.")

# ---------------- PDE5 inhibitors ----------------
pde_table = """<h2>Compared</h2>
<ul class="tx"><li><span class="ev m">Fast, short</span><b>Sildenafil</b> (Viagra and generics)<dl><dt>Starts</dt><dd>30–60 minutes; slower after a fatty meal</dd><dt>Lasts</dt><dd>About 4–5 hours</dd><dt>Doses</dt><dd>25–100 mg, about an hour before sex</dd><dt>Quirk</dt><dd>Blue-tinged or blurred vision in some</dd></dl></li>
<li><span class="ev m">Long-acting</span><b>Tadalafil</b> (Cialis and generics)<dl><dt>Starts</dt><dd>30 minutes to 2 hours; food doesn’t matter</dd><dt>Lasts</dt><dd>Up to 36 hours (“the weekend pill”)</dd><dt>Doses</dt><dd>10–20 mg as needed, or 5 mg every day</dd><dt>Quirk</dt><dd>Back and muscle aches; 5 mg daily also eases prostate urine symptoms</dd></dl></li>
<li><span class="ev m">Fast, short</span><b>Vardenafil</b> (Levitra and generics)<dl><dt>Starts</dt><dd>25–60 minutes</dd><dt>Lasts</dt><dd>About 4–5 hours</dd><dt>Doses</dt><dd>5–20 mg</dd><dt>Quirk</dt><dd>Avoid with some heart rhythm medicines</dd></dl></li></ul>
"""
med("pde5-inhibitors", "PDE5 Inhibitors (Sildenafil, Tadalafil): ED, Prostate and More",
 "Sildenafil, tadalafil and vardenafil compared: how they work for erectile dysfunction, daily tadalafil for prostate symptoms, side effects, the nitrate warning and cost.",
 "PDE5 inhibitors", "Phosphodiesterase-5 inhibitors",
 [("m", "Medicine family"), ("l", "Prescription only (S4)")],
 "Sildenafil, tadalafil and vardenafil. They don’t create desire; they help blood flow do its job when you’re aroused. Also used for prostate symptoms and high blood pressure in the lungs.",
 "PDE5 inhibitors (sildenafil, tadalafil, vardenafil) treat erectile dysfunction by improving blood flow when you’re sexually aroused. They work for about 2 in 3 men. Tadalafil lasts up to 36 hours and, at 5 mg daily, also eases prostate urine symptoms. Common side effects are headache, flushing, a blocked nose and indigestion. Never take them with nitrates (angina sprays or tablets) or amyl nitrite (“poppers”).",
 [("For", "Erectile dysfunction; prostate urine symptoms (daily tadalafil); pulmonary arterial hypertension (specialist)"),
  ("Works", "Firmer erections for about 2 in 3 men; less after prostate surgery or with severe diabetes"),
  ("Cost", "Not on the PBS for erectile dysfunction (except some veterans): a private script; generics are much cheaper than the brands"),
  ("Kicks in", "30–60 minutes; arousal is still needed"),
  ("Dose", "As needed before sex, or tadalafil 5 mg daily; lower doses with some medicines and kidney or liver disease"),
  ("Watch for", "Headache, flushing, blocked nose, indigestion, back pain, dizziness")],
 "Plumbing, not mood. It needs arousal to work, and it’s a check-up prompt: erection problems can be an early sign of heart disease.",
 ["Sildenafil: Viagra and many generics", "Tadalafil: Cialis and many generics", "Vardenafil: Levitra and generics"],
 "An erection happens when nitric oxide relaxes the blood vessels in the penis so blood flows in. PDE5 is the enzyme that switches that signal off. Blocking it keeps the signal on for longer, but only once arousal has started it.",
 ["Erectile dysfunction (TGA-approved)", "Prostate enlargement urine symptoms: tadalafil 5 mg daily (TGA-approved)",
  "Pulmonary arterial hypertension: specific brands and doses, specialist-prescribed",
  "Off label: Raynaud’s phenomenon, altitude sickness prevention in some people, sexual side effects of antidepressants"],
 "Headache and flushing are the most common, followed by a blocked nose, indigestion and dizziness. Tadalafil more often causes back and muscle aches; sildenafil can tint vision blue. Serious effects are rare.",
 [g(V, ["Headache"]),
  g(C, ["Flushing", "Blocked or runny nose", "Indigestion or reflux", "Dizziness", "Back or muscle aches (tadalafil)", "Vision changes: blue tinge, blur, light sensitivity (sildenafil)"]),
  g(U, ["Palpitations or fast heartbeat", "Low blood pressure or fainting", "Nosebleeds", "Eye pain or red eyes", "Painful erections"]),
  g(R, ["<b>Priapism</b> (erection over 4 hours)", "<b>Sudden vision loss</b> (NAION)", "<b>Sudden hearing loss</b>", "<b>Heart attack, stroke or heart rhythm problems</b> (mostly in people with heart disease)", "<b>Severe allergic reactions</b>"])],
 ["An erection lasting more than 4 hours: go to an emergency department", "Sudden loss of vision or hearing", "Chest pain during or after sex: stop, don’t take a nitrate, call 000 and tell them you took a PDE5 inhibitor", "Fainting"],
 ["<b>Never with nitrates</b> (glyceryl trinitrate spray or tablets, isosorbide) or “poppers”: blood pressure can crash. Not with riociguat.",
  "<b>Alpha blockers</b> (e.g. tamsulosin, prazosin): start low and space doses; dizziness is more likely.",
  "Grapefruit and some antibiotics, antifungals and HIV medicines raise levels.",
  "Avoid heavy alcohol; it worsens dizziness and erections.",
  "<b>Get checked:</b> erection problems can be an early sign of heart disease, diabetes or low testosterone. Buy only from an Australian pharmacy: online fakes are common."],
 [("Do PDE5 inhibitors work without arousal?", "No. They help blood flow once you’re sexually aroused, but they don’t create desire or an erection on their own."),
  ("What’s the difference between sildenafil and tadalafil?", "Sildenafil works for about 4–5 hours and is slowed by fatty food. Tadalafil lasts up to 36 hours, isn’t affected by food, and can be taken as 5 mg daily, which also helps prostate urine symptoms."),
  ("Why can’t you take Viagra with nitrates?", "Both lower blood pressure, and together they can cause a dangerous drop. That includes angina sprays and tablets and amyl nitrite (“poppers”).")],
 [("Viagra product information (TGA)", "https://www.ebs.tga.gov.au/"), ("Cialis product information (TGA)", "https://www.ebs.tga.gov.au/"),
  ("Healthy Male: Erectile dysfunction", "https://www.healthymale.org.au/mens-health/erectile-dysfunction"), HD],
 [("Erectile Dysfunction", "/erectile-dysfunction/"), ("Enlarged Prostate", "/enlarged-prostate/"), ("Low Libido in Men", "/low-libido-men/")],
 index_label="Medicine family", blurb="Sildenafil, tadalafil and vardenafil compared. For erectile dysfunction, prostate symptoms and lung blood pressure.",
 extra=pde_table)
